package com.fasterxml.jackson.databind.jsontype.impl;

import com.fasterxml.jackson.annotation.JsonTypeInfo;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.type.TypeFactory;
import com.fasterxml.jackson.databind.util.ClassUtil;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class ClassNameIdResolver__idFrom_TriageGen0Test {

    private TypeFactory typeFactory;
    private ClassNameIdResolver resolver;
    private JavaType baseType;

    // Helper classes for testing inner class logic and enums
    public enum TestEnum { A, B }
    public static class Outer {
        public static class Inner {}
        public static class StaticInner {}
    }
    public static class NonStaticOuter {
        public class NonStaticInner {}
    }

    @Before
    public void setUp() {
        ObjectMapper mapper = new ObjectMapper();
        typeFactory = mapper.getTypeFactory();
        baseType = typeFactory.constructType(Object.class);

        // Since _idFrom is protected, we use a subclass to expose it for testing
        resolver = new ClassNameIdResolver(baseType, typeFactory) {
            @Override
            public String idFromValueAndType(Object value, Class<?> type) {
                // This is a workaround to call the protected method via reflection or direct call if visible to subclass
                try {
                    java.lang.reflect.Method method = ClassNameIdResolver.class.getDeclaredMethod("_idFrom", Object.class, Class.class, TypeFactory.class);
                    method.setAccessible(true);
                    return (String) method.invoke(this, value, type, typeFactory);
                } catch (Exception e) {
                    throw new RuntimeException(e);
                }
            }

            // Exposing the protected method for the test
            public String callIdFrom(Object value, Class<?> cls, TypeFactory tf) {
                return _idFrom(value, cls, tf);
            }
        };
    }

    @Test
    public void testStandardClass() {
        String result = resolver.callIdFrom(new Object(), String.class, typeFactory);
        assertEquals("java.lang.String", result);
    }

    @Test
    public void testEnumSubclassLogic() {
        // If cls is an enum, it returns cls.getName()
        // If cls is a subclass of Enum (not possible in Java, but testing the logic branch)
        // The code checks: if (Enum.class.isAssignableFrom(cls) && !cls.isEnum())
        // In Java, you can't extend Enum, but we test the standard Enum path
        String result = resolver.callIdFrom(new Object(), TestEnum.class, typeFactory);
        assertEquals("com.fasterxml.jackson.databind.jsontype.impl.ClassNameIdResolver__idFrom_TriageGen0Test$TestEnum", result);
    }

    @Test
    public void testEnumSet() {
        EnumSet<TestEnum> enumSet = EnumSet.of(TestEnum.A);
        // The logic uses ClassUtil.findEnumType which is internal to Jackson
        // We assume ClassUtil works as intended for standard EnumSet
        String result = resolver.callIdFrom(enumSet, EnumSet.class, typeFactory);
        // Expected canonical form: java.util.EnumSet[com.fasterxml.jackson.databind.jsontype.impl.ClassNameIdResolver__idFrom_TriageGen0Test$TestEnum]
        // Note: actual string depends on Jackson's TypeFactory.toCanonical()
        assertEquals("java.util.EnumSet[com.fasterxml.jackson.databind.jsontype.impl.ClassNameIdResolver__idFrom_TriageGen0Test$TestEnum]", result);
    }

    @Test
    public void testEnumMap() {
        EnumMap<TestEnum, Object> enumMap = new EnumMap<>(TestEnum.class);
        String result = resolver.callIdFrom(enumMap, EnumMap.class, typeFactory);
        assertEquals("java.util.EnumMap[com.fasterxml.jackson.databind.jsontype.impl.ClassNameIdResolver__idFrom_TriageGen0Test$TestEnum,java.lang.Object]", result);
    }

    @Test
    public void testArraysAsListWrapper() {
        List<String> list = Arrays.asList("a", "b");
        // Arrays.asList returns an internal class like java.util.Arrays$ArrayList
        String result = resolver.callIdFrom(list, list.getClass(), typeFactory);
        assertEquals("java.util.ArrayList", result);
    }

    @Test
    public void testCollectionsWrapper() {
        List<String> list = Collections.singletonList("a");
        // Collections.singletonList returns java.util.Collections$SingletonList
        String result = resolver.callIdFrom(list, list.getClass(), typeFactory);
        assertEquals("java.util.ArrayList", result);
    }

    @Test
    public void testOtherJavaUtilClass() {
        // Test a java.util class that doesn't trigger the special List logic
        String result = resolver.callIdFrom(new HashMap<>(), HashMap.class, typeFactory);
        assertEquals("java.util.HashMap", result);
    }

    @Test
    public void testInnerClassWithStaticType() {
        // Test the logic: if (str.indexOf('$') >= 0)
        // If the outer class is null (not possible for real inner classes) or 
        // if the baseType's raw class has no outer class, it falls back to baseType.

        // Mocking the resolver to control _baseType via reflection if needed, 
        // but we can use the constructor.
        JavaType mockBaseType = mock(JavaType.class);
        when(mockBaseType.getRawClass()).thenReturn(Object.class);

        ClassNameIdResolver resolverWithMock = new ClassNameIdResolver(mockBaseType, typeFactory) {
            public String callIdFrom(Object value, Class<?> cls, TypeFactory tf) {
                try {
                    java.lang.reflect.Method method = ClassNameIdResolver.class.getDeclaredMethod("_idFrom", Object.class, Class.class, TypeFactory.class);
                    method.setAccessible(true);
                    return (String) method.invoke(this, value, cls, tf);
                } catch (Exception e) {
                    throw new RuntimeException(e);
                }
            }
        };

        // Outer.Inner is a static inner class. ClassUtil.getOuterClass(Outer.Inner.class) returns Outer.class.
        // Since Outer.class has no outer class, it hits the branch: cls = _baseType.getRawClass()
        String result = resolverWithMock.callIdFrom(new Outer.Inner(), Outer.Inner.class, typeFactory);
        assertEquals("java.lang.Object", result);
    }

    @Test
    public void testNonStaticInnerClass() {
        // For a non-static inner class, the behavior depends on ClassUtil and _baseType
        // This test ensures we hit the branch where an outer class is found.
        JavaType mockBaseType = mock(JavaType.class);
        when(mockBaseType.getRawClass()).thenReturn(NonStaticOuter.class);

        ClassNameIdResolver resolverWithMock = new ClassNameIdResolver(mockBaseType, typeFactory) {
            public String callIdFrom(Object value, Class<?> cls, TypeFactory tf) {
                try {
                    java.lang.reflect.Method method = ClassNameIdResolver.class.getDeclaredMethod("_idFrom", Object.class, Class.class, TypeFactory.class);
                    method.setAccessible(true);
                    return (String) method.invoke(this, value, cls, tf);
                } catch (Exception e) {
                    throw new RuntimeException(e);
                }
            }
        };

        // NonStaticOuter.NonStaticInner$Inner
        // ClassUtil.getOuterClass(NonStaticInner.class) returns NonStaticOuter.class
        // ClassUtil.getOuterClass(NonStaticOuter.class) returns null
        // Therefore, it goes into the if (outer != null) block, then checks staticType (NonStaticOuter)
        // staticType's outer is null, so it sets cls = _baseType.getRawClass() (NonStaticOuter)
        String result = resolverWithMock.callIdFrom(new NonStaticOuter().new NonStaticInner(), NonStaticOuter.NonStaticInner.class, typeFactory);
        assertEquals("NonStaticOuter", result);
    }
}
